@import "tailwindcss";

@custom-variant dark (&:where(.dark, .dark *));

@theme {
  --color-scorch-crimson: #D62436;
  --color-scorch-dark: #9B1B30;
  --color-scorch-cyan: #4DA3FF;
  --color-scorch-gold: #F4D35E;
  --color-scorch-gold-text: #B45309;

  --color-canvas-paper: #F5F7FA;
  --color-canvas-surface: #FFFFFF;
  --color-canvas-hacker: #0B0F17;
  --color-canvas-dark-surface: #111827;

  --shadow-brutal-sm: -2px 2px 0px 0px var(--shadow-color, #000000);
  --shadow-brutal: -4px 4px 0px 0px var(--shadow-color, #000000);
  --shadow-brutal-lg: -6px 6px 0px 0px var(--shadow-color, #000000);
  --shadow-brutal-xl: -8px 8px 0px 0px var(--shadow-color, #000000);

  --font-pixel: 'Press Start 2P', 'VT323', monospace;
  --font-sub: 'Tiny5', 'VT323', monospace;
  --font-mono: 'JetBrains Mono', monospace;

  /* Emil Kowalski Custom Mechanical Easings (Zero-Lag Punch) */
  --ease-mechanical: cubic-bezier(0.23, 1, 0.32, 1);
  --ease-smooth: cubic-bezier(0.77, 0, 0.175, 1);
}

:root {
  /* TEMA CLARO: Paper Brutalism */
  color-scheme: light;
  --bg-canvas: #F5F7FA;
  --bg-surface: #FFFFFF;
  --bg-header: #0A0E14;
  --text-main: #111111;
  --text-muted: #334155;
  --text-inverted: #FFFFFF;
  --border-main: #000000;
  --shadow-color: #000000;
  --dither-color: #94A3B8;
  --ascii-color: #D62436;

  /* Paleta Velgrynd (Calibrada WCAG AA >= 4.5:1) */
  --scorch-red: #D62436;
  --scorch-dark: #9B1B30;
  --cyber-blue: #4DA3FF;
  --eye-gold: #F4D35E;
  --eye-gold-contrast: #B45309;
  --shadow-offset-x: -4px;
  --shadow-offset-y: 4px;
  --dither-size: 12px;
}

html.dark {
  /* TEMA OSCURO: Hacker CRT */
  color-scheme: dark;
  --bg-canvas: #0B0F17;
  --bg-surface: #111827;
  --bg-header: var(--scorch-red, #D62436);
  --text-main: #F8FAFC;
  --text-muted: #CBD5E1;
  --text-inverted: #FFFFFF;
  --border-main: #E2E8F0;
  --shadow-color: var(--scorch-red, #D62436);
  --dither-color: #1E293B;
  --ascii-color: #FF4D5A;
  --eye-gold-contrast: #F4D35E;
}

html, body {
  max-width: 100vw;
  overflow-x: clip;
  touch-action: manipulation;
  -webkit-tap-highlight-color: transparent;
}

body {
  background-color: var(--bg-canvas);
  color: var(--text-main);
  font-family: 'JetBrains Mono', monospace;
  background-image: radial-gradient(var(--dither-color) 1.25px, transparent 1.25px);
  background-size: var(--dither-size, 12px) var(--dither-size, 12px);
  min-height: 100vh;
}

/* Foco de accesibilidad brutalista */
:focus-visible {
  outline: 2px dashed var(--scorch-red) !important;
  outline-offset: 4px !important;
}

/* Tipografía Display */
.title-8bit {
  font-family: 'Press Start 2P', 'VT323', monospace;
  text-transform: uppercase;
  -webkit-text-stroke: 1.5px #000000;
  text-shadow: var(--shadow-offset-x, -4px) var(--shadow-offset-y, 4px) 0px #000000;
  line-height: 1.35;
  letter-spacing: -0.02em;
}

html.dark .title-8bit {
  -webkit-text-stroke: 1.5px #000000;
  text-shadow: var(--shadow-offset-x, -4px) var(--shadow-offset-y, 4px) 0px var(--scorch-red, #D62436);
}

.subtitle-pixel {
  font-family: 'Tiny5', 'VT323', monospace;
  text-transform: uppercase;
  letter-spacing: 0.14em;
}

/* Clases canónicas (Animaciones GPU composited con curva Emil Kowalski) */
.btn-brutal {
  border: 2px solid var(--border-main);
  box-shadow: var(--shadow-offset-x, -4px) var(--shadow-offset-y, 4px) 0px 0px var(--shadow-color);
  font-family: 'JetBrains Mono', monospace;
  font-weight: 800;
  text-transform: uppercase;
  transition: transform 75ms var(--ease-mechanical);
  will-change: transform;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  border-radius: 0px;
  user-select: none;
}

@media (hover: hover) and (pointer: fine) {
  .btn-brutal:hover {
    transform: translate(2px, -2px);
    box-shadow: -6px 6px 0px 0px var(--shadow-color);
  }
}

.btn-brutal:active {
  transform: translate(var(--shadow-offset-x, -4px), var(--shadow-offset-y, 4px));
  box-shadow: 0px 0px 0px 0px var(--shadow-color);
}

.tui-window {
  background-color: var(--bg-surface);
  border: 2px solid var(--border-main);
  box-shadow: var(--shadow-offset-x, -4px) var(--shadow-offset-y, 4px) 0px 0px var(--shadow-color);
  border-radius: 0px;
}

.tui-header {
  background-color: var(--bg-header);
  color: var(--text-inverted);
  border-bottom: 2px solid var(--border-main);
  padding: 0.4rem 0.85rem;
  font-size: 0.75rem;
  font-weight: 800;
  display: flex;
  justify-content: space-between;
  align-items: center;
  user-select: none;
}

/* Native HTML5 Dialog / Modal Standards con transición Emil Kowalski (scale 0.96 -> 1) */
dialog:modal {
  overscroll-behavior: contain;
  margin: auto;
  padding: 0;
  border-radius: 0px;
  opacity: 0;
  transform: scale(0.96);
  transition: opacity 150ms ease-out, transform 150ms var(--ease-mechanical), display 150ms allow-discrete, overlay 150ms allow-discrete;
}

dialog[open]:modal {
  opacity: 1;
  transform: scale(1);
}

@starting-style {
  dialog[open]:modal {
    opacity: 0;
    transform: scale(0.96);
  }
}

dialog::backdrop {
  overflow: hidden;
  overscroll-behavior: contain;
  background-color: rgba(11, 15, 23, 0);
  backdrop-filter: blur(0px);
  transition: background-color 150ms ease-out, backdrop-filter 150ms ease-out, display 150ms allow-discrete, overlay 150ms allow-discrete;
}

dialog[open]::backdrop {
  background-color: rgba(11, 15, 23, 0.78);
  backdrop-filter: blur(2px);
}

@starting-style {
  dialog[open]::backdrop {
    background-color: rgba(11, 15, 23, 0);
    backdrop-filter: blur(0px);
  }
}

/* Transición nativa para Popover API */
[popover] {
  opacity: 0;
  transform: scale(0.96);
  transition: opacity 150ms ease-out, transform 150ms var(--ease-mechanical), display 150ms allow-discrete, overlay 150ms allow-discrete;
}

[popover]:popover-open {
  opacity: 1;
  transform: scale(1);
}

@starting-style {
  [popover]:popover-open {
    opacity: 0;
    transform: scale(0.96);
  }
}

/* Accesibilidad: Reducción de movimiento */
@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
    scroll-behavior: auto !important;
  }
}
